/*********************
* Health bar colours *
*********************/

.template-healthbar {
	display: flex;
	flex-direction: column;
}

.template-healthbar > .template-healthbar-icons,
.template-healthbar > .template-healthbar-effects {
	display: flex;
	flex-direction: row;
	text-align: center;

	padding: 4px;
	gap: 4px;
}

.template-healthbar > .template-healthbar-effects {
	border: 1px solid #FFF;
	border-radius: 8px;
}

.template-healthbar > .template-healthbar-icons > div {
	display: flex;
	justify-content: center;

	/* Transparent border to share alignment */
	border: 4px solid transparent;
}

.template-healthbar > .template-healthbar-icons a {
	display: flex;
	justify-content: center;
	width: 0px;
}

.template-healthbar > .template-healthbar-effects > div {
	height: 20px;
	border: 4px solid var(--status-effect-color);
	background-image: repeating-linear-gradient(
		-60deg,
		var(--status-effect-trans) 0 12px,
		var(--status-effect-color) 10px 20px
	);
	border-radius: 4px;
}

.template-healthbar .template-healthbar-arrow {
	--status-effect-color: #d1a072;
	--status-effect-trans: #d1a0725c;
}
.template-healthbar .template-healthbar-cold {
	--status-effect-color: #00bcff;
	--status-effect-trans: #00bcff5c;
}
.template-healthbar .template-healthbar-curse {
	--status-effect-color: #100730;
	--status-effect-trans: #1007305c;
}
.template-healthbar .template-healthbar-crab {
	--status-effect-color: #e13542;
	--status-effect-trans: #e135425c;
}
.template-healthbar .template-healthbar-damage,
.template-healthbar .template-healthbar-injury {
	--status-effect-color: #ff5300;
	--status-effect-trans: #ff53005c;
}
.template-healthbar .template-healthbar-drowsy {
	--status-effect-color: #ff5ca4;
	--status-effect-trans: #ff5ca45c;
}
.template-healthbar .template-healthbar-flytrap {
	--status-effect-color: #187b32;
	--status-effect-trans: #187b325c;
}
.template-healthbar .template-healthbar-heat {
	--status-effect-color: #c80918;
	--status-effect-trans: #c809185c;
}
.template-healthbar .template-healthbar-hunger {
	--status-effect-color: #ffbd16;
	--status-effect-trans: #ffbd165c;
}
.template-healthbar .template-healthbar-petrify {
	--status-effect-color: #858cab;
	--status-effect-trans: #858cab5c;
}
.template-healthbar .template-healthbar-poison {
	--status-effect-color: #a139ff;
	--status-effect-trans: #a139ff5c;
}
.template-healthbar .template-healthbar-spores {
	--status-effect-color: #a65c63;
	--status-effect-trans: #a65c635c;
}
.template-healthbar .template-healthbar-thorns {
	--status-effect-color: #768e00;
	--status-effect-trans: #768e005c;
}
.template-healthbar .template-healthbar-web {
	--status-effect-color: #e6e6e7;
	--status-effect-trans: #e6e6e75c;
