/**********************
* Starts custom DRUID *
*** This will get moved when it's more "final" ***
**********************/
.druid-infobox .druid-title {
	font-family: var(--wiki-content-heading-font-family);
	font-weight: 400;
	font-size: 1.5rem;
	padding-bottom: .25rem; /* add padding DarumaDrop is short */
}
.druid-infobox .druid-section {
	font-family: var(--wiki-content-heading-font-family);
	font-size: 1.25rem;
	padding-bottom: .25rem; /* add padding DarumaDrop is short */
}

.druid-data .scoutStatus-label {
	display: none;
}

.druid-grid-section-Attributes .druid-grid-item,
.druid-grid-section-Attributes .druid-grid-item.posEffect {
	background-color: rgba(50, 205, 50, .15);
}

.druid-grid-section-Attributes .druid-grid-item.negEffect {
	background-color: rgba(255, 0, 0, .15);
}

.druid-grid-section-Attributes .druid-grid-item-Poison:has(div.focused[data-druid-tab-key="Poisonous"]) {
	background-color: rgba(255, 0, 0, .15); /* Poison in Poisonous tab should always be a neagtive and therefore red background */
}

.druid-infobox ul.hlist.tags {
	margin: 0; /* remove any normal bullet list margin */
}

.druid-infobox ul.hlist.tags dd:not(:last-child)::after, 
.druid-infobox ul.hlist.tags li:not(:last-child)::after {
	display: none; /* remove any normal bullet list bullets */
}

.druid-infobox .tags .tag {
    border: 1px solid var(--wiki-content-border-color);
    display: inline-block;
    padding: 0 4px;
    border-radius: 3px;
    margin: 3px 6px 3px auto;
}

.druid-infobox .tags .tag a {
    white-space: nowrap;
}

/********************
* End custom DRUID *
*******************/

.scout_badge.locked {
