/*************
* Biome List *
*************/

.peakTimerTable > .peakTimerUpper {
	text-align: center;
}

.peakTimerTable > .peakTimerUpper > .clockBox {
	display: inline-block;

	border: 2px solid var(--wiki-content-border-color);
	border-radius: 25%;
	background: color-mix(in srgb,var(--wiki-content-background-color--secondary) 100%,transparent);

	padding: 1em;
}

.peakTimerTable > .peakTimerLower {
	display: flex;
	flex-direction: row;

	border: 2px solid var(--wiki-content-border-color);
	border-radius: 1em;
	overflow: hidden;
}

.peakTimerTable > .peakTimerLower > .biomeBox {
	display: flex;
	flex-direction: column;
	flex-grow: 1;
	flex-basis: 0;

	background-position: center;
	background-size: cover;

	text-align: center;
	justify-content: center;

	aspect-ratio: 2/1;

	font-family: var(--wiki-content-firstheading-font-family,var(--wiki-content-heading-font-family));
	font-size: 1.65rem;
	color: #FFF;
}

.biomeBox span {
	height: 100%;
    background: rgba(0, 0, 0, .2);
    align-content: center;
	text-shadow:  1px 1px 2px black,  0 0 1em black,  0 0 0.2em black;
}

@media screen and (max-width: 1100px) {
	.peakTimerTable > .peakTimerLower {
		display: grid;
		grid-template-columns: repeat(2, 1fr);
	}

	.peakTimerTable > .peakTimerLower > .biomeBox {
		aspect-ratio: auto;
		line-height: normal;
		height: 48px;
	}
	.peakTimerTable > .peakTimerLower a:nth-of-type(1) {
		grid-column: 1 / span 2;
