/* These variables are designed to inherit from your wiki's color variables.
   If your wiki uses a different naming scheme, change the inner names to match yours.
   If your wiki doesn't use color variables you should consider doing so,
   otherwise you can replace the inner variables or the fallback values with colors that match your wiki.
*/

/* Light and dark are separated to make it easier for you to do local customizations but in the default version they are identical */

:root, .view-light .druid-container {
    --druid-background-color: var(--wiki-content-background-color, #ffffff);

    --druid-secondary-background-color: var(--wiki-accent-color, #36c);
    --druid-secondary-background-label-color: var(--wiki-accent-label-color, #fff);

    --druid-tertiary-background-color: var(--wiki-content-background-color--secondary, #eaecf0);

    --druid-border-color: var(--wiki-content-border-color, #a7d7f9);

    --druid-link-color: var(--wiki-content-link-color, #0645ad);
    --druid-link-label-color: var(--wiki-content-link-label-color, #fff);
}

.view-dark .druid-container {
    --druid-background-color: var(--wiki-content-background-color, #ffffff);

    --druid-secondary-background-color: var(--wiki-accent-color, #36c);
    --druid-secondary-background-label-color: var(--wiki-accent-label-color, #fff);

    --druid-tertiary-background-color: var(--wiki-content-background-color--secondary, #eaecf0);

    --druid-border-color: var(--wiki-content-border-color, #a7d7f9);

    --druid-link-color: var(--wiki-content-link-color, #0645ad);
    --druid-link-label-color: var(--wiki-content-link-label-color, #fff);
}

/* Custom DRUID styles should go here */

/* ****** ****** ****** */
/* Important for modified Tabbed images layout  */
.druid-main-images .druid-main-image:not(.focused) {
	display: none;
}

.druid-main-image-caption {
	text-align: center;
}
/* End modified Tabbed images layout  */
/* ****** ****** ****** */

/* *** Section heading backgrounds *** */
.druid-container {
	--druid-heading-background: color-mix(in srgb,var(--druid-secondary-background-color) 75%,transparent); /* default druid */
	--druid-heading-background: var(--druid-secondary-background-color);
}
.view-dark .druid-infobox .druid-title {
	/* support for top title banner in dark mode */
	color: var(--wiki-content-text-color);
}
.druid-infobox .druid-title, .druid-infobox .druid-section {
	background: var(--druid-heading-background);
}

/* *** Title header stitched background *** */
.druid-infobox .druid-title {
	border-image-source: url(filepath://Red_Ribbon.png);
    border-image-slice: 0 56 0 58 fill;
    border-image-width: 0px 56px 0px 58px;
    /* border-image-outset: 2px 16px 0; */
    border-image-repeat: round stretch;
	background: #84222a;
}

/* *** Tabs backgrounds *** */
.druid-main-images-label {
	--highlight-accent: #5198DD;
	border-radius: 4px;
	outline: 1px solid var(--wiki-content-border-color);
	background: var(--wiki-navigation-background-color);
}

.druid-main-images-label.focused {
	font-weight: 700;
	outline: 1px solid var(--wiki-accent-color);
	background: var(--wiki-accent-color);
}

.druid-main-images-label:hover,
.druid-main-images-label:not(.focused):hover {
	background: color-mix(in srgb,var(--wiki-accent-color) 50%,transparent);
	background: color-mix(in srgb,gold 75%,transparent);
	color: var(--wiki-content-text-color);
}

.druid-main-images-label:hover {
	background: var(--highlight-accent);
	color: var(--druid-secondary-background-label-color);
}

/* *** Image frame for items *** */
.druid-container-item .druid-main-image-file {
	background-color: #DFDBC2;
	border: 8px solid #BFAA8F;
	border-radius: 30px;
	width: max-content;
	margin: 0 auto;
}

/* *** Status Effect grid layout adjustments *** */
div[data-druid-section-row="BaseStatusEffects"] .druid-grid-item {
	display:flex;
	flex-direction: column;
}

div[data-druid-section-row="BaseStatusEffects"] .druid-grid-item .druid-label {
	flex-grow: 2;
	padding-bottom: 2px;
	align-content: center;
}
div[data-druid-section-row="BaseStatusEffects"] .druid-grid-item .druid-data {
	align-content: end;
	border-radius: 4px;
}

/* *** Status Effect backgrounds *** */
.druid-grid-item.posEffect {
	background-color: color-mix(in srgb, transparent, #32cd32 15%);
}
.druid-grid-item.negEffect {
    background-color: color-mix(in srgb, transparent, #ff0000 15%);
}
.druid-grid-item.posEffect .druid-data,
.druid-grid-item.negEffect .druid-data {
	background-color: color-mix(in srgb, var(--druid-background-color) 40%, transparent);
	border: 1px solid color-mix(in srgb, var(--druid-border-color) 25%,transparent);
}

