/* Any JavaScript here will be loaded for all users on every page load. */
$(function () {
	///////////////////////////////////////////////////////////////////////////////
	// Shared Constants and Utilities
	///////////////////////////////////////////////////////////////////////////////

	const RESET_HOUR_UTC = 17; // 5PM UTC = 10AM PST
	const RESET_MINUTE_UTC = 0;
	const RESET_YEAR = 2026;
	const RESET_MONTH = 10;
	const RESET_DAY = 02;

	// Configurable start date: set this to the day the patch was uploaded (months are zero‑indexed so with use -1 there for JS which wants it zero-indexed)
	const START_DATE = new Date(Date.UTC(RESET_YEAR, RESET_MONTH - 1, RESET_DAY, RESET_HOUR_UTC, RESET_MINUTE_UTC, 0));

	// Normalize a given time to the last reset boundary
	function getResetBoundary(time) {
		const currentDate = new Date(time);
		const boundary = new Date(Date.UTC(
			currentDate.getUTCFullYear(),
			currentDate.getUTCMonth(),
			currentDate.getUTCDate(),
			RESET_HOUR_UTC,
			RESET_MINUTE_UTC,
			0
		));
		if (currentDate < boundary) {
			boundary.setUTCDate(boundary.getUTCDate() - 1);
		}
		return boundary;
	}

	// Next reset time (used for scheduling)
	function getNextResetTime(refTime = new Date()) {
		const boundary = new Date(Date.UTC(
			refTime.getUTCFullYear(),
			refTime.getUTCMonth(),
			refTime.getUTCDate(),
			RESET_HOUR_UTC,
			RESET_MINUTE_UTC,
			0
		));
		if (refTime >= boundary) {
			boundary.setUTCDate(boundary.getUTCDate() + 1);
		}
		return boundary;
	}

	function padTime(value) {
		return Math.floor(value).toString().padStart(2, '0');
	}

///////////////////////////////////////////////////////////////////////////////
//
// PEAK Island Reset Clock... displays a constant timer counting down to the PEAK map reset
//

	const $timers = $('.peakMapClock');
	if ($timers.length > 0) {
		function getUTCTimeInSeconds() {
			const now = new Date();
			return now.getUTCHours() * 3600 + now.getUTCMinutes() * 60 + now.getUTCSeconds();
		}

		function calculateCountdown(targetHour, targetMinute) {
			const nowInSeconds = getUTCTimeInSeconds();
			let targetTimeInSeconds = targetHour * 3600 + targetMinute * 60;

			if (targetTimeInSeconds < nowInSeconds) {
				targetTimeInSeconds += 24 * 3600;
			}
			return targetTimeInSeconds - nowInSeconds;
		}

		function updateResetClock() {
			const countdown = calculateCountdown(RESET_HOUR_UTC, RESET_MINUTE_UTC);
			const hours = Math.floor(countdown / 3600);
			const minutes = Math.floor((countdown % 3600) / 60);
			const seconds = countdown % 60;
			$timers.text(`${hours}h ${minutes}m ${seconds}s`);
		}

		// Initial call on load
		updateResetClock();
		// Update every 1 second
		setInterval(updateResetClock, 1000);
	}
//* End Peak Island Reset Clock */

///////////////////////////////////////////////////////////////////////////////
// 
// PEAK Biome List... display the daily list of biomes
//
// Select the map container
const $mapContainer = $('.peakTimerTable');
if ($mapContainer.length > 0) {
	// Biome metadata
	const biomeData = {
		airport: { name: 'Airport' },
		alpine: { name: 'Alpine' },
		caldera: { name: 'Caldera' },
		kiln: { name: 'Kiln' },
		mesa: { name: 'Mesa' },
		peak: { name: 'Peak', page: 'Peak_(biome)' },
		roots: { name: 'Roots' },
		beach: { name: 'Shore' },
		shore: { name: 'Shore' },
		tropics: { name: 'Tropics' },
		gloom: { name: 'Gloom' },
		citadel: { name: 'Citadel' },
	};

	// Biome variations schedule array
	const biomeVariations = [
	// Level_13 from 2026-10-02 to 2026-10-03
		['shore', 'roots', 'alpine', 'gloom', 'citadel'],
	// Level_14 from 2026-10-03 to 2026-10-04
		['shore', 'tropics', 'alpine', 'caldera', 'kiln'],
	// Level_15 from 2026-10-04 to 2026-10-05
		['shore', 'tropics', 'mesa', 'gloom', 'citadel'],
	// Level_16 from 2026-10-05 to 2026-10-06
		['shore', 'roots', 'alpine', 'caldera', 'kiln'],
	// Level_17 from 2026-10-06 to 2026-10-07
		['shore', 'tropics', 'alpine', 'gloom', 'citadel'],
	// Level_18 from 2026-10-07 to 2026-10-08
		['shore', 'roots', 'mesa', 'caldera', 'kiln'],
	// Level_19 from 2026-10-08 to 2026-10-09
		['shore', 'tropics', 'mesa', 'gloom', 'citadel'],
	// Level_20 from 2026-10-09 to 2026-10-10
		['shore', 'roots', 'alpine', 'caldera', 'kiln'],
	// Level_0 from 2026-10-10 to 2026-10-11
		['shore', 'tropics', 'mesa', 'caldera', 'kiln'],
	// Level_1 from 2026-10-11 to 2026-10-12
		['shore', 'roots', 'mesa', 'gloom', 'citadel'],
	// Level_2 from 2026-10-12 to 2026-10-13
		['shore', 'roots', 'alpine', 'caldera', 'kiln'],
	// Level_3 from 2026-10-13 to 2026-10-14
		['shore', 'tropics', 'alpine', 'gloom', 'citadel'],
	// Level_4 from 2026-10-14 to 2026-10-15
		['shore', 'tropics', 'mesa', 'caldera', 'kiln'],
	// Level_5 from 2026-10-15 to 2026-10-16
		['shore', 'roots', 'mesa', 'gloom', 'citadel'],
	// Level_6 from 2026-10-16 to 2026-10-17
		['shore', 'roots', 'alpine', 'caldera', 'kiln'],
	// Level_7 from 2026-10-17 to 2026-10-18
		['shore', 'tropics', 'alpine', 'gloom', 'citadel'],
	// Level_8 from 2026-10-18 to 2026-10-19
		['shore', 'tropics', 'mesa', 'caldera', 'kiln'],
	// Level_9 from 2026-10-19 to 2026-10-20
		['shore', 'roots', 'alpine', 'gloom', 'citadel'],
	// Level_10 from 2026-10-20 to 2026-10-21
		['shore', 'tropics', 'alpine', 'caldera', 'kiln'],
	// Level_11 from 2026-10-21 to 2026-10-22
		['shore', 'tropics', 'mesa', 'gloom', 'citadel'],
	// Level_12 from 2026-10-22 to 2026-10-23
		['shore', 'roots', 'mesa', 'caldera', 'kiln'],
	];

	// for (let i = 0; i < biomeVariations.length; i++) {
		// biomeVariations[i].unshift('shore'); // Prepend "shore"
	//	biomeVariations[i].push('caldera', 'kiln'); // Append "caldera" and "kiln"
	// }

	function getVariationForDate(time) {
		const currentReset = getResetBoundary(time);
		const daysPassed = Math.floor((currentReset - START_DATE) / (24 * 60 * 60 * 1000));
		const index = ((daysPassed % biomeVariations.length) + biomeVariations.length) % biomeVariations.length;
		return biomeVariations[index];
	}

	// Store biome link elements
	const biomeLinks = [];

	// Hook into MediaWiki content load
	mw.hook('wikipage.content').add(function () {
		const $mapList = $mapContainer.find('> .peakTimerLower');
		// Exit early if no such element exists
		if ($mapList.length === 0) return;

		function updateBiomes(time) {
			const biomeSchedule = getVariationForDate(time);

			for (let i = 0; i < biomeSchedule.length; i++) {
				const biomeKey = biomeSchedule[i];
				const biome = biomeData[biomeKey];
				if (!biome) {
					console.warn(`Unknown biome key: ${biomeKey}`);
					continue;
				}

				let $link = biomeLinks[i];
				if (!$link) {
					$link = $('<a>', { class: `peakTimerBiome${i}` }).appendTo($mapList);
					biomeLinks[i] = $link;
				}

				const page = biome.page || biome.name;
				const href = `/wiki/${page.replace(/ /g, '_')}`;

				$link
					.attr('href', href)
					.html(`<span>${biome.name}</span>`)
					.removeClass((_, classNames) => {
						if (!classNames) return '';
						return classNames
							.split(' ')
							.filter(cls => cls.startsWith('biomeBox_'))
							.join(' ');
					})
					.addClass('biomeBox')
					.addClass(`biomeBox_${biomeKey}`);
			}
		}

			let resetTime = getResetBoundary(new Date());
			updateBiomes(resetTime);

		// Refresh biomes every 30 mins
			setInterval(() => {
				const newResetTime = getNextResetTime();
				if (newResetTime.getTime() !== resetTime.getTime()) {
					resetTime = newResetTime;
					updateBiomes(getResetBoundary(new Date())); // <-- current boundary
				}
			}, 30 * 60 * 1000);
		});
	}
});
//* End Peak Biome List */

