/* 
 * Modified from https://dev.fandom.com/wiki/MediaWiki:ScrollUpButton.js
 * Original version at https://zh.wikipedia.org/wiki/MediaWiki:Gadget-scrollUpButton.js
 */

$(()=>{


    /* CONFIG, you can edit these variables */
    var buttonOutlineColor = 'var(--wiki-accent-color, #3066CD)'; // the color of the arrow
    var buttonBackgroundColor = 'var(--wiki-accent-label-color, white)'; // the color of the background
    var buttonSize = '32'; /* in px, but write it unitless */
    var buttonFadeoutTime = 2000; /* in ms, how long after scrolling before the button fades. Set to 0 for it to not fade */
    var includeDownButton = true; /* set to false to have only a scroll up button, but no scroll down */
    /* end editable config */


    // construct the svg used for the button image, inserting our variables
	var scrollButtonIcon = '<?xml version="1.0"?><svg height="' + buttonSize + '" viewBox="0 0 512 512" width="' + buttonSize + '" xmlns="http://www.w3.org/2000/svg" class="scrollButtonIcon"><g opacity="0.8" stroke="' + buttonOutlineColor + '" stroke-linejoin="round" stroke-width="46"><circle opacity="1" cx="256" cy="256" fill="' + buttonBackgroundColor + '" r="227"/><path d="m378 270l-114-118 0 240h-17.1l0-240-114 118-11.6-12.8 134-134 134 134z" fill="' + buttonOutlineColor + '"/></g></svg>';

    // create the down button
	$scrollDownButton = $('<div>', {
		id: 'scrollDownButton',
        html: scrollButtonIcon
	}).css({
		cursor: 'pointer',
		opacity: 0.7,
		position: 'fixed',
		display: 'none',
		right: '18px',
        bottom: '24px',
		transform: 'rotate(180deg)',
	}).on('click', function() {
		$('html, body').animate({ // scroll to the bottom of the page over the course of 660 ms
			scrollTop: $(document).height() - $(window).height()
		}, 660)
	}).on('mouseenter mouseleave', function(e) {
		this.style.opacity = e.type === 'mouseenter' ? 1 : 0.7
	}).appendTo('body');

    // create the up button
	$scrollUpButton = $('<div>', {
		id: 'scrollUpButton',
        html: scrollButtonIcon
	}).css({
		cursor: 'pointer',
		opacity: 0.7,
		position: 'fixed',
		display: 'none',
		right: '18px',
        bottom: includeDownButton ? '65px' : '24px', // if we don't have a down button, put the up button closer to the bottom
	}).on('click', function() {
		$('html, body').animate({ // scroll to the top of the page over the course of 660 ms
			scrollTop: 0
		}, 660)
	}).on('mouseenter mouseleave', function(e) {
		this.style.opacity = e.type === 'mouseenter' ? 1 : 0.7 // when we mouse into the button, set opacity to 1, otherwise set it to 0.7
	}).appendTo('body');

	var scrollButtonTimer;
	$(window).on('scroll', function() {

		if($(this).scrollTop() > 60){ // if we're more than 60px from the top of the page, fade the buttons in
            includeDownButton ? $scrollDownButton.fadeIn('slow') : null ; // don't fade the down button in if we're not using it
            $scrollUpButton.fadeIn('slow');
        }
        else { // otherwise fade them out
            $scrollDownButton.fadeOut('slow');
            $scrollUpButton.fadeOut('slow');
        }

        if(buttonFadeoutTime > 0){

            this.clearTimeout(scrollButtonTimer); // reset the fade timer
            scrollButtonTimer = this.setTimeout(function() { // queue the buttons to slowly fade out after the given time
                $scrollDownButton.fadeOut('slow');
                $scrollUpButton.fadeOut('slow');
            }, buttonFadeoutTime)
        }
	});

    if(buttonFadeoutTime > 0){ // if we aren't using a fade timer, we don't need to set these listeners

        $scrollDownButton.on('mouseenter', function() {
            window.clearTimeout(scrollButtonTimer)
        });

        $scrollUpButton.on('mouseenter', function() {
            window.clearTimeout(scrollButtonTimer)
        })
    }

});

