$(document).ready(function() {

// Create the input dynamically
const input = document.createElement("input");
input.type = "text";
input.className = "filterInput";
input.placeholder = "Search table...";
input.setAttribute("aria-label", "Search table"); // accessibility label

// Create the search icon span
const searchIcon = document.createElement("span");
searchIcon.className = "peak-searchIcon";

// Wrap input and icon in a span
const inputWrapper = document.createElement("span");
inputWrapper.className = "peak-inputWidget";
inputWrapper.appendChild(input);
inputWrapper.appendChild(searchIcon);

// Create the dropdown dynamically
const select = document.createElement("select");
select.className = "filterSelect";
select.setAttribute("aria-label", "Filter table by item type");

// Initially disabled with "No filters available"
const placeholder = document.createElement("option");
placeholder.textContent = "No filters available";
select.appendChild(placeholder);
select.disabled = true;

// Find the table
const table = document.querySelector(".filterTable");
const rows = Array.from(table.getElementsByTagName("tr"));
const itemTypes = new Set();

// Collect unique data-itemType values (split by commas)
for (let i = 1; i < rows.length; i++) { // skip header row
	const cells = rows[i].getElementsByTagName("td");
	for (let j = 0; j < cells.length; j++) {
		const itemTypeAttr = cells[j].getAttribute("data-itemType");
		if (itemTypeAttr) {
			itemTypeAttr.split(",").forEach(type => {
				const normalized = type.trim().toLowerCase();
				if (normalized) {
					itemTypes.add(normalized);
				}
			});
		}
	}
}

// Populate dropdown list
if (itemTypes.size > 0) {
	select.disabled = false;
	select.innerHTML = ""; // clear placeholder

	const allOption = document.createElement("option");
	allOption.value = "All";
	allOption.textContent = "All";
	select.appendChild(allOption);

	// Define food group subtypes
	const foodTypes = new Set([
		"food", // All food
		"berries",
		"mushrooms",
		"natural food",
		"packaged food",
		]);

	// Create optgroups
	const foodGroup = document.createElement("optgroup");
	foodGroup.label = "Food";

	const otherGroup = document.createElement("optgroup");
	otherGroup.label = "Other items";

	// Sort alphabetically before adding
	Array.from(itemTypes)
		.map(type => {
			// Custom label: "food" becomes "All food"
			const label = (type === "food")
				? "All food"
				: type.charAt(0).toUpperCase() + type.slice(1);

			return { value: type, label };
		})
		.sort((a, b) => a.label.localeCompare(b.label))
		.forEach(({ value, label }) => {
			const option = document.createElement("option");
			option.value = value;
			option.textContent = label;

			if (foodTypes.has(value) || value === "food") {
				foodGroup.appendChild(option);
			} else {
				otherGroup.appendChild(option);
			}
		});

	// Append groups only if they contain items
	if (foodGroup.children.length > 0) select.appendChild(foodGroup);
	if (otherGroup.children.length > 0) select.appendChild(otherGroup);
}

// Create a label span before the dropdown
const filterLabel = document.createElement("span");
filterLabel.className = "peak-filterLabel";
filterLabel.textContent = "Filter:";

// Create the reset button
const resetBtn = document.createElement("button");
resetBtn.className = "peak-resetBtn";
resetBtn.textContent = "Reset";
resetBtn.setAttribute("aria-label", "Reset filters");
resetBtn.disabled = true; // start disabled

// Create wrapping div with new class
const container = document.createElement("div");
container.className = "peak-tableWidget";

// Order: Filter label + dropdown, then search input + icon, then reset button
container.appendChild(filterLabel);
container.appendChild(select);
container.appendChild(inputWrapper);
container.appendChild(resetBtn);

// Insert container before the table
table.parentNode.insertBefore(container, table);

// Attach filter function to input, select, and reset
input.addEventListener("keyup", filterTable);
select.addEventListener("change", filterTable);
resetBtn.addEventListener("click", resetFilters);

// Add rounded corners for last visible row
function updateRoundedCorners() {
	// remove old class
	rows.forEach(row => row.classList.remove("rounded-last"));

	// find visible non-header rows 
	const visible = rows.slice(1).filter(r => r.style.display !== "none");

	if (visible.length > 0) {
		visible[visible.length - 1].classList.add("rounded-last");
	}
}

// Filter function
function filterTable() {
	const filter = input.value.toLowerCase();
	// Treat disabled dropdown as "All"
	const typeFilter = select.disabled ? "all" : select.value.toLowerCase();
	const rows = table.getElementsByTagName("tr");

	for (let i = 1; i < rows.length; i++) { // skip header row
		const cells = rows[i].getElementsByTagName("td");
		let matchText = false;
		let matchType = false;

		// Text search across all cells
		for (let j = 0; j < cells.length; j++) {
			const txtValue = cells[j].textContent || cells[j].innerText;
			if (filter && txtValue.toLowerCase().includes(filter)) {
				matchText = true;
			}

			// Check data-itemType attribute (split by commas)
			const itemTypeAttr = cells[j].getAttribute("data-itemType");
			if (itemTypeAttr) {
				const types = itemTypeAttr.split(",").map(t => t.trim().toLowerCase());
				if (typeFilter === "all" || types.includes(typeFilter)) {
					matchType = true;
				}
			}
		}

		// Show row only if both filters match
		rows[i].style.display = ((!filter || matchText) && matchType) ? "" : "none";
	}

	// Enable reset button only if filters are active
	const resetActive = (filter.length > 0) || (!select.disabled && select.value.toLowerCase() !== "all");
	resetBtn.disabled = !resetActive;

	updateRoundedCorners();
}

function resetFilters() {
	input.value = "";
	// Reset dropdown to "All" if enabled, otherwise leave disabled
	if (!select.disabled) {
		select.value = "All";
	}
	filterTable(); // re-run filter to show all rows

	updateRoundedCorners();
}

});

