/******************************************************/
/*                                                    */
/* [END] OF WIKI.GG DEFAULT LOADOUT                   */
/* ALL LOCAL SKIN CUSTOMIZATIONS SHOULD GO BELOW HERE */
/* DO NOT EDIT OR DELETE THIS COMMENT BLOCK           */
/*                                                    */
/******************************************************/

/* Custom Sidebar */
#mw-panel .vector-menu-portal + .vector-menu-portal {
    border-top-width: 0;
    box-shadow: inset 0px 5px 5px -5px var(--wiki-content-text-color);
}

#mw-panel .vector-menu-portal:not(:last-child) {
    border-bottom-width: 0;
}

.vector-menu-portal .vector-menu-content {
    background-image: url(filepath://A_Dots_1.png);
    background-color: var(--wiki-content-background-color);
    background-blend-mode: color-burn;
    background-size: 2em;
    background-position: center;
    margin: 0.25em;
    border-radius: 0.5em;
}

.view-dark .vector-menu-portal .vector-menu-content {
    background-blend-mode: soft-light;
}

.vector-menu-portal .vector-menu-content ul {
    padding: 0.25em;
    font-weight: bold;
    border-radius: 0.5em;
    background-color: var(--wiki-content-background-color);
}

#p-logo + .mw-portlet .vector-menu-heading {
	display: inherit;
}

@media screen and (max-width: 720px) { /* style mobile nav menu to match to search */
	body.has-vector-mobile-menu #mw-panel .mobile-nav-toggle {
		border-radius: 6px;
		background-color: var(--wiki-navigation-search-background-color);		
		border-width: 2px;
	}
}

/* Custom Navigation Tabs */
.vector-menu-tabs .mw-list-item a,
.vector-menu-tabs .mw-list-item a:visited,
#mw-head .vector-menu-dropdown .vector-menu-heading {
	font-family: var(--wiki-heading-font-family);
	font-weight: 400;
}

.vector-search-box-input {
    border-radius: 1em 1em 0 0;
}
/* Custom Search tweaks */

#p-search {
	padding: 0 1rem 0 0;
}

#p-search input {
	line-height: 1.5;
}

#p-search button {
	right: var(--wiki-navigation-selected-border-width);
}

@media screen and (max-width: 720px) {
	.cdx-text-input__input {
		line-height: 1.5;
	}

	#searchInput { /* mobile */
		border-radius: 6px;
		border: 2px solid var(--wiki-navigation-background-color);
		border: 2px solid var(--wiki-content-border-color);
	}
}


/* Custom Content */
.mw-body,
.parsoid-body {
    outline: 0.5em solid var(--wiki-content-border-color--secondary);
    background-image: url(filepath://A_Dots_1.png);
    background-color: var(--wiki-content-background-color);
    background-blend-mode: color-burn;
    background-size: 2em;
    background-position: center;
    border-radius: 0.5em;
}

.view-dark .mw-body,
.view-dark .parsoid-body {
    background-blend-mode: soft-light;
}

#mw-content-text {
    background-color: var(--wiki-content-background-color);
    border-radius: 1em;
    padding: 0.5em 1em;
    /*background-image: url(filepath://Site-background.jpg);
    background-blend-mode: multiply;*/
}

#contentSub,
#contentSub2 {
    background-color: var(--wiki-content-background-color);
    border-radius: 0.5em;
    padding: 0 5px;
}

/* Custom Footer */
.mw-footer {
	--boarding-pass-top-margin: 40px;
	--boarding-pass-bottom-margin: 10px;
    padding: calc(var(--boarding-pass-top-margin) + 1em) 1em calc(var(--boarding-pass-bottom-margin) + 1em);
    outline: 0.5em solid var(--wiki-content-border-color--secondary);
}

@media screen and (min-width: 721px) {

	.mw-footer {
		--boarding-pass-top-margin: 40px;
		--boarding-pass-bottom-margin: 10px;
		display: grid;
		grid-template-areas:
			'bar info separator icons'
			'bar places separator icons';
		grid-template-columns: 50px 1fr 1em 350px;
		padding: 0 1em;
		outline: 0.5em solid var(--wiki-content-border-color--secondary);
	}

	.mw-footer #footer-info,
	.mw-footer #footer-icons {
		margin-top: calc(var(--boarding-pass-top-margin) + 1em);
	}

	.mw-footer #footer-places,
	.mw-footer #footer-icons {
		margin-bottom: calc(var(--boarding-pass-bottom-margin) + 1em);
	}

	.mw-footer #footer-info { grid-area: info; }
	.mw-footer #footer-places { grid-area: places; }

	.mw-footer #footer-icons {
		grid-area: icons;
		display: flex;
		align-items: center;
		background-color: #314BFA;
		border-radius: 1em;
		margin-left: 5px;
	}

	.mw-footer::before {
		grid-area: separator;
		display: block;
		content: "";
		height: 100%;
		border-image: url(filepath://Boarding_pass_dashed_line.png) 8 0 9 5 / 0px 0px 0px 6px;
		border-image-repeat: stretch repeat;
	}

	.mw-footer::after {
		grid-area: bar;
		background: url(filepath://Boarding_pass_barcode.png) no-repeat;
		background-size: contain;
		margin: var(--boarding-pass-top-margin) 0 var(--boarding-pass-bottom-margin);
		image-rendering: pixelated;
	}
}

/* Other Custom Tweaks */
.oo-ui-buttonElement.oo-ui-labelElement > input.oo-ui-buttonElement-button,
.oo-ui-buttonElement.oo-ui-labelElement > .oo-ui-buttonElement-button > .oo-ui-labelElement-label {
    border-radius: 0.5em;
}


#left-navigation::before {
	width: 1.0em;
}
@media screen and (max-width: 720px) {
	#left-navigation::before {
		width: var(--wiki-navigation-left-spacing, 0px);
	}
}

.vector-menu-tabs .mw-list-item,.vector-menu-dropdown {
    padding-bottom: 0px;
}

.vector-menu-tabs .mw-list-item.selected a,
.vector-menu-tabs .mw-list-item a, .vector-menu-tabs .mw-list-item a:visited, #mw-head .vector-menu-dropdown .vector-menu-heading {
	border-color: var(--wiki-navigation-background-color);
	border-bottom-color:var(--wiki-navigation-border-bottom-color); 
	border-bottom-width: 0px;
	border-top-width: 0px;
	padding-top: 0.40em;
	padding-bottom: 0.1em;
	margin-bottom: 0.5em;
}

.vector-menu-tabs .mw-list-item.selected a {
	border-color: var(--wiki-content-border-color--secondary);
	border-top-width: var(--wiki-navigation-selected-border-width);
	padding-bottom: 0.6em;
	margin-bottom: 0;
	background-image: url(filepath://A_Dots_1.png);
    background-color: var(--wiki-content-background-color);
    background-blend-mode: color-burn;
    background-size: 2em;
    background-repeat: repeat;
}

.view-dark .vector-menu-tabs .mw-list-item.selected a {
	background-blend-mode: soft-light;
}

.vector-menu-tabs .mw-list-item a:hover,
#mw-head .vector-menu-dropdown:hover .vector-menu-heading {
	border-color: transparent;
}

.vector-menu-tabs .mw-list-item.selected a:hover{
	border-color: var(--wiki-content-border-color--secondary);
}

div.vector-menu-dropdown:hover {
	border-radius: var(--wiki-navigation-border-radius) var(--wiki-navigation-border-radius) 0 0;
}


.vector-menu-tabs #ca-watch.icon a, .vector-menu-tabs #ca-unwatch.icon a {
	padding-top: 0.30em;
	padding-bottom: 0.2em;
}
/************
* Wikitable *
************/

.wikitable > tr > th, .wikitable > * > tr > th {
    background: var(--wiki-navigation-background-color);
}

table.wikitable {
	--wiki-table-border-color: var(--wiki-content-background-color);	
	--wiki-table-background-color: var(--wiki-content-border-color);
	--wiki-table-inner-radius: 9px;
	border: 4px solid var(--wiki-table-border-color);
	background: var(--wiki-table-background-color);
	border-radius: 14px;
    border-collapse: separate;
    border-spacing: revert;
}

table.wikitable th,
table.wikitable td {
	border: none;
}

table.wikitable td {
	background: var(--background-color-neutral-subtle,#f8f9fa);
}

table.wikitable tr:first-child th:first-child {
    border-top-left-radius: var(--wiki-table-inner-radius);
    border-bottom-left-radius: 0;
}

table.wikitable tr:first-child th:last-child {
    border-top-right-radius: var(--wiki-table-inner-radius);
    border-bottom-left-radius: 0;
}

table.wikitable tbody tr:last-child > :first-child {
    border-bottom-left-radius: var(--wiki-table-inner-radius);
}

table.wikitable tbody tr:last-child > :last-child {
    border-bottom-right-radius: var(--wiki-table-inner-radius);
}

table.wikitable tr.rounded-last > :first-child {
    border-bottom-left-radius: 9px;
}
table.wikitable tr.rounded-last > :last-child {
    border-bottom-right-radius: 9px;
}

/*** Wikitable sorting tweak ***/
.client-js .sortable:not(.jquery-tablesorter) > * > tr:first-child > th:not(.unsortable)::after,
.jquery-tablesorter th.headerSort::after {
	background-color: var(--wiki-content-text-color);
}

/*** Mobile navigation toggle button ***/
( function () {
	const BUTTON_CLASS = 'mobile-nav-toggle';
	const EXPANDED_CLASS = 'nav--expanded';
	if (document.querySelector('button.' + BUTTON_CLASS)){return;} // early return to avoid double button if this runs twice

	let mobileSidebarButton = document.createElement( 'button' );
	let sidebar = document.getElementById( 'mw-panel' );
	mobileSidebarButton.className = BUTTON_CLASS;
	mobileSidebarButton.addEventListener( 'click', function () {
		mobileSidebarButton.classList.toggle( EXPANDED_CLASS );
		sidebar.classList.toggle( EXPANDED_CLASS );
	} );
	sidebar.prepend( mobileSidebarButton );
	document.body.classList.add( 'has-vector-mobile-menu' );
} )();
/*** End mobile navigation toggle button ***/

/*** #mw-head collapsing fix ***/
/*** IMPORTANT: Do not copy this code if your wiki is not updated to default loadout 2.0 (May 22, 2025) or later, or your navigation tabs will break ***/
mw.loader.using('skins.vector.legacy.js', function() {
	$.collapsibleTabs.calculateTabDistance = function(){
		return parseInt(window.getComputedStyle(document.getElementById( 'right-navigation' ), '::before').width ) - 1;
	}
});
/*** END #mw-head collapsing fix ***/
